package com.nook.widgets.test;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import com.nook.widgets.*;
import org.json.JSONObject;
import java.io.*;
import java.time.LocalDate;
import java.util.function.BiConsumer;

/** Checks actual native clock/layout behavior and exports reviewable compositions. */
public final class ReplicaSmoke {
    public static void run(Instrumentation i,Context c,JSONObject photo,JSONObject weather,JSONObject music,BiConsumer<Boolean,String> check){
        pixelGeometry(c,check);
        Activity activity=i.startActivitySync(new Intent(c,WidgetConfigActivity.class).putExtra("kind","clock").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK));i.waitForIdleSync();
        try{i.runOnMainSync(()->{
            for(int design:new int[]{1,2,3,4,7})try{
                for(int face=0;face<4;face++)for(boolean compact:new boolean[]{false,true}){
                    JSONObject config=Widgets.defaults("clock");WidgetDesign.select(config,design);config.put("clockFace",face).put("variant",1);View v=Widgets.render(c,-1,"clock",config,compact,true).apply(c,new FrameLayout(c));measure(c,v,320,compact?182:250);
                    int selected=face==0?(design==2||design==3||design==4?2:1):face;
                    if(selected==2){View analog=v.findViewById(config.optInt("style",0)==3?(WidgetDesign.colors(config,"clock").text==android.graphics.Color.WHITE?com.nook.widgets.R.id.replica_clock_glassdark:com.nook.widgets.R.id.replica_clock_glasslight):design==1?com.nook.widgets.R.id.replica_clock_dot:design==4?com.nook.widgets.R.id.replica_clock_pixel:design==7?com.nook.widgets.R.id.replica_clock_samsung:com.nook.widgets.R.id.replica_clock_apple);check.accept(analog instanceof AnalogClock&&analog.getVisibility()==View.VISIBLE&&analog.getHeight()>=Ui.dp(c,90),"Native analog face fits design "+design);check.accept(v.findViewById(com.nook.widgets.R.id.widget_time).getVisibility()==View.GONE,"Analog clock has one time display");if(design==4){Rect bounds=new Rect();analog.getDrawingRect(bounds);((ViewGroup)v).offsetDescendantRectToMyCoords(analog,bounds);check.accept(Math.abs(bounds.exactCenterX()-v.getWidth()/2f)<1,"Pixel clock view is horizontally centered in both sizes");}}
                    else{TextClock clock=v.findViewById(com.nook.widgets.R.id.widget_time);check.accept(clock.getVisibility()==View.VISIBLE&&clock.getHeight()>0,"Native digital clock is visible");check.accept(clock.getFormat24Hour().toString().equals(selected==3?"HH\nmm":"HH:mm"),"Clock face retains its 24-hour setting");check.accept(clock.getBottom()<=v.getHeight(),"Clock numerals remain inside the widget");}
                }
                JSONObject root=Widgets.defaults("universal");WidgetDesign.select(root,design);root.put("page","weather");UniversalWidget.pageSettings(root,"weather").put("city",weather.optString("city")).put("latitude",weather.optDouble("latitude")).put("longitude",weather.optDouble("longitude"));View universal=Widgets.render(c,-1,"universal",root,false,true).apply(c,new FrameLayout(c));measure(c,universal,320,340);check.accept(universal.findViewById(com.nook.widgets.R.id.widget_settings).getVisibility()==View.GONE,"Embedded replica has no duplicate customize button");if(design==2||design==3){WidgetDesign.Colors outer=WidgetDesign.colors(root,"universal"),inner=WidgetDesign.colors(UniversalWidget.viewConfig(root,"weather"),"weather");check.accept(outer.surface==inner.surface&&outer.text==inner.text,"Universal weather retains readable sky colors");}
                for(int height:new int[]{180,205,250}){JSONObject note=Widgets.defaults("notes");WidgetDesign.select(note,design);note.put("_width",280).put("_height",height);View noteView=Widgets.render(c,-1,"notes",note,false,true).apply(c,new FrameLayout(c));measure(c,noteView,280,height);View capture=noteView.findViewById(com.nook.widgets.R.id.widget_action0);Rect bounds=new Rect();capture.getDrawingRect(bounds);((android.view.ViewGroup)noteView).offsetDescendantRectToMyCoords(capture,bounds);check.accept(capture.getVisibility()==View.VISIBLE&&bounds.bottom<=noteView.getHeight()-Ui.dp(c,8),"Note capture fits design "+design+" at "+height+"dp");}
                board(c,activity,design,photo,weather,music);
            }catch(Exception e){throw new RuntimeException("Replica design="+design,e);}
        });}finally{i.runOnMainSync(activity::finish);}
    }
    private static Bitmap raster(Context c,int resource,int size){Bitmap b=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);android.graphics.drawable.Drawable d=c.getDrawable(resource).mutate();d.setBounds(0,0,size,size);d.draw(new Canvas(b));return b;}
    private static double[] center(Bitmap b,boolean hub){double weight=0,xTotal=0,yTotal=0;int left=b.getWidth(),top=b.getHeight(),right=-1,bottom=-1;for(int y=0;y<b.getHeight();y++)for(int x=0;x<b.getWidth();x++){int pixel=b.getPixel(x,y),alpha=Color.alpha(pixel);if(alpha==0||hub&&(pixel&0xffffff)!=0x9abf20)continue;weight+=alpha;xTotal+=(x+.5)*alpha;yTotal+=(y+.5)*alpha;left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}return new double[]{xTotal/weight,yTotal/weight,(left+right+1)/2.0,(top+bottom+1)/2.0};}
    private static void pixelGeometry(Context c,BiConsumer<Boolean,String> check){
        for(int size:new int[]{180,320,512}){Bitmap dial=raster(c,com.nook.widgets.R.drawable.dial_pixel,size);try{double[] face=center(dial,false);check.accept(Math.abs(face[0]-size/2.0)<.35&&Math.abs(face[1]-size/2.0)<.35,"Pixel face's visible centroid is centered at "+size+"px");check.accept(Math.abs(face[2]-size/2.0)<.5&&Math.abs(face[3]-size/2.0)<.5,"Pixel face bounds are symmetric at "+size+"px");for(int resource:new int[]{com.nook.widgets.R.drawable.hand_pixel_hour,com.nook.widgets.R.drawable.hand_pixel_minute}){Bitmap hand=raster(c,resource,size);try{double[] pivot=center(hand,true);check.accept(Math.abs(pivot[0]-face[0])<.5&&Math.abs(pivot[1]-face[1])<.5,"Pixel hand hub coincides with the visible dial center");}finally{hand.recycle();}}boolean contained=true;for(int angle=0;angle<360;angle+=5){double radians=Math.toRadians(angle);int x=(int)(size*(100+76.5*Math.sin(radians))/200),y=(int)(size*(100-76.5*Math.cos(radians))/200);contained&=Color.alpha(dial.getPixel(x,y))>240;}check.accept(contained,"Pixel minute hand remains within every lobe at "+size+"px");}finally{dial.recycle();}}
    }
    private static void measure(Context c,View v,int w,int h){v.measure(View.MeasureSpec.makeMeasureSpec(Ui.dp(c,w),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(Ui.dp(c,h),View.MeasureSpec.EXACTLY));v.layout(0,0,v.getMeasuredWidth(),v.getMeasuredHeight());}
    private static void board(Context c,Activity activity,int design,JSONObject photo,JSONObject weather,JSONObject music)throws Exception{
        String key=switch(design){case 1->"nothing";case 2->"apple";case 3->"macos";case 4->"pixel";default->"samsung";};String[] kinds={"notes","clock","weather","calendar","battery","music","photos","timers"};Bitmap b=Bitmap.createBitmap(1600,2580,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(0xffe6e5e1);Paint p=new Paint(3);p.setColor(0xff242525);p.setTextSize(34);p.setTypeface(Typeface.create("sans-serif-medium",0));canvas.drawText(WidgetDesign.NAMES[design],36,54,p);p.setTextSize(21);canvas.drawText("Native Android widgets · Data-driven layouts · Labeled sample photo, weather and music",36,91,p);
        for(int n=0;n<kinds.length;n++){String kind=kinds[n];JSONObject config=new JSONObject((kind.equals("photos")?photo:kind.equals("weather")?weather:kind.equals("music")?music:Widgets.defaults(kind)).toString());WidgetDesign.select(config,design);config.put("_width",280).put("_height",205);if(kind.equals("notes"))config.put("noteActions",false);if(kind.equals("weather"))config.put("variant",1);int x=36+n%2*790,y=123+n/2*600;p.setTextSize(22);p.setColor(0xff474947);canvas.drawText(Widgets.title(kind),x,y+24,p);FrameLayout frame=new FrameLayout(c);if(config.optInt("style")!=0)frame.setBackgroundResource(com.nook.widgets.R.drawable.preview_wallpaper);View view=Widgets.render(c,-1,kind,config,false,true).apply(c,frame);frame.addView(view,new FrameLayout.LayoutParams(-1,-1));ViewGroup display=activity.findViewById(android.R.id.content);display.addView(frame,new ViewGroup.LayoutParams(Ui.dp(c,280),Ui.dp(c,205)));frame.measure(View.MeasureSpec.makeMeasureSpec(Ui.dp(c,280),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(Ui.dp(c,205),View.MeasureSpec.EXACTLY));frame.layout(0,0,frame.getMeasuredWidth(),frame.getMeasuredHeight());canvas.save();canvas.translate(x,y+42);canvas.scale(740f/frame.getWidth(),540f/frame.getHeight());frame.draw(canvas);canvas.restore();display.removeView(frame);}
        File dir=new File(c.getFilesDir(),"screenshots");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,"replica-"+key+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}
    }
}
